1	package dashboard
2	
3	import (
4		"bytes"
5		"fmt"
6		"os"
7		"path"
8		"path/filepath"
9		"strings"
10	
11		"gopkg.in/yaml.v3"
12	)
13	
14	// messagesDirName is the per-system directory holding authored message
15	// descriptions: one Markdown file per connector, named after it
16	// (messages/<connector>.md), with YAML frontmatter for the structured facts
17	// and free prose in the body.
18	const messagesDirName = "messages"
19	
20	// maxMessageBodyBytes caps the prose body served for one message description.
21	const maxMessageBodyBytes = 16 * 1024
22	
23	// messageDoc is an authored description of the payload a connector carries —
24	// the flat file from an SFTP drop, the ad-hoc CSV export — written by a
25	// developer because no machine spec exists. It is documentation, not
26	// enforcement: the runtime never validates against it. Contact and
27	// LastReviewed are its staleness story.
28	type messageDoc struct {
29		Format       string     `json:"format,omitempty" yaml:"format"`
30		Delimiter    string     `json:"delimiter,omitempty" yaml:"delimiter"`
31		Encoding     string     `json:"encoding,omitempty" yaml:"encoding"`
32		FilePattern  string     `json:"filePattern,omitempty" yaml:"filePattern"`
33		Frequency    string     `json:"frequency,omitempty" yaml:"frequency"`
34		Contact      string     `json:"contact,omitempty" yaml:"contact"`
35		LastReviewed string     `json:"lastReviewed,omitempty" yaml:"lastReviewed"`
36		Fields       []docField `json:"fields,omitempty" yaml:"fields"`
37		Sample       *docSample `json:"sample,omitempty" yaml:"sample"`
38		Body         string     `json:"body,omitempty" yaml:"-"`
39	}
40	
41	// docField describes one field or column of an external payload. Type is
42	// loose by design (string/integer/decimal/date/boolean/other) — it records
43	// what the author knows, not a validatable schema.
44	type docField struct {
45		Name     string `json:"name" yaml:"name"`
46		Position int    `json:"position,omitempty" yaml:"position"`
47		Type     string `json:"type,omitempty" yaml:"type"`
48		Required bool   `json:"required,omitempty" yaml:"required"`
49		Notes    string `json:"notes,omitempty" yaml:"notes"`
50	}
51	
52	// docSample is a short inline payload excerpt. Redacted is a pointer so an
53	// author cannot publish a sample without explicitly asserting they considered
54	// what it exposes — an absent value rejects the sample, not defaults it.
55	type docSample struct {
56		Inline   string `json:"inline" yaml:"inline"`
57		Redacted *bool  `json:"redacted" yaml:"redacted"`
58	}
59	
60	// readMessageDocs collects the authored message descriptions under a system
61	// directory, keyed by connector name (the filename). Problems are returned as
62	// strings for the report's error banner — a broken doc never fails the
63	// request, and error paths are relative to dir so callers can prefix the
64	// system's identifier.
65	func readMessageDocs(dir string) (map[string]messageDoc, []string) {
66		ents, err := os.ReadDir(filepath.Join(dir, messagesDirName))
67		if err != nil {
68			return nil, nil
69		}
70		var docs map[string]messageDoc
71		var errs []string
72		for _, ent := range ents {
73			if ent.IsDir() || !strings.HasSuffix(ent.Name(), ".md") {
74				continue
75			}
76			rel := path.Join(messagesDirName, ent.Name())
77			data, err := os.ReadFile(filepath.Join(dir, messagesDirName, ent.Name()))
78			if err != nil {
79				errs = append(errs, fmt.Sprintf("%s: %v", rel, err))
80				continue
81			}
82			doc, docErrs := parseMessageDoc(data)
83			for _, e := range docErrs {
84				errs = append(errs, fmt.Sprintf("%s: %s", rel, e))
85			}
86			if doc == nil {
87				continue
88			}
89			if docs == nil {
90				docs = map[string]messageDoc{}
91			}
92			docs[strings.TrimSuffix(ent.Name(), ".md")] = *doc
93		}
94		return docs, errs
95	}
96	
97	// parseMessageDoc splits a doc into YAML frontmatter and prose body. A file
98	// without frontmatter is a valid prose-only description. A doc is only
99	// rejected (nil) when its frontmatter does not parse; lesser problems drop
100	// the offending part and report it.
101	func parseMessageDoc(data []byte) (*messageDoc, []string) {
102		meta, body := splitFrontmatter(data)
103		var doc messageDoc
104		if len(meta) > 0 {
105			if err := yaml.Unmarshal(meta, &doc); err != nil {
106				return nil, []string{fmt.Sprintf("invalid frontmatter: %v", err)}
107			}
108		}
109		var errs []string
110		if doc.Sample != nil && doc.Sample.Redacted == nil {
111			doc.Sample = nil
112			errs = append(errs, "sample dropped: set redacted: true|false to assert the sample was checked for sensitive data")
113		}
114		if len(body) > maxMessageBodyBytes {
115			body = body[:maxMessageBodyBytes]
116		}
117		doc.Body = strings.TrimSpace(string(body))
118		return &doc, errs
119	}
120	
121	// splitFrontmatter separates a leading YAML frontmatter block (delimited by
122	// "---" lines) from the document body. Without an opening delimiter on the
123	// first line the whole input is body.
124	func splitFrontmatter(data []byte) (meta, body []byte) {
125		normalized := bytes.ReplaceAll(data, []byte("\r\n"), []byte("\n"))
126		rest, ok := bytes.CutPrefix(normalized, []byte("---\n"))
127		if !ok {
128			return nil, normalized
129		}
130		if meta, body, ok = bytes.Cut(rest, []byte("\n---\n")); ok {
131			return meta, body
132		}
133		// Closing delimiter at end-of-file without a trailing newline.
134		if meta, ok = bytes.CutSuffix(rest, []byte("\n---")); ok {
135			return meta, nil
136		}
137		// No closing delimiter: not frontmatter after all.
138		return nil, normalized
139	}
